def parse_json_at(src, key):
    # 两种写法都支持：lore_core 里是 JSON 属性 "KEY": {...}，map_data 里是 KEY = [...]
    m = re.search(r'"%s":\s*(\{|\[)' % key, src) or re.search(r'%s\s*=\s*(\{|\[)' % key, src)
    if not m:
        return None
    start = m.end() - 1
    depth, i, instr, esc = 0, start, False, False
    while i < len(src):
        c = src[i]
        if instr:
            if esc:
                esc = False
            elif c == "\\":
                esc = True
            elif c == '"':
                instr = False
        else:
            if c == '"':
                instr = True
            elif c in "[{":
                depth += 1
            elif c in "]}":
                depth -= 1
                if depth == 0:
                    break
        i += 1
    return json.loads(src[start:i + 1])


ERA_EN_KEYS = set(ERAS_EN.keys())


def main():
    lore = open(os.path.join(ROOT, "js/lore_core.js"), encoding="utf-8").read()
    mapd = open(os.path.join(ROOT, "js/map_data.js"), encoding="utf-8").read()

    polities = parse_json_at(lore, "POLITY_PROFILES") or []
    persons = parse_json_at(lore, "PERSON_PROFILES") or []
    places = parse_json_at(lore, "PLACE_GAZETTEER") or []
    passes = parse_json_at(lore, "STRATEGIC_PASSES") or []
    dyn = parse_json_at(mapd, "DYNASTY_DATA") or []

    dict_map = {}
    for p in polities:
        if p.get("en"):
            dict_map[p["zh"]] = p["en"]
    for p in persons:
        if p.get("en"):
            dict_map[p["zh"]] = p["en"]
    for ps in passes:
        dict_map[ps["ancientZh"]] = ps.get("ancientEn") or ps["ancientZh"]
        if ps.get("modernZh") and ps.get("modernEn"):
            dict_map[ps["modernZh"]] = ps["modernEn"]
    for pl in places:
        lat = next((a for a in (pl.get("aliases") or []) if re.match(r"^[A-Za-z]", str(a))), None)
        if lat:
            dict_map[pl["name"]] = lat
        if pl.get("modern") and re.match(r"^[A-Za-z]", str(pl.get("modern") or "")):
            dict_map[pl["modern"]] = pl["modern"]
    for d in dyn:
        en = ERAS_EN.get(d["key"])
        if en:
            dict_map[d["title"]] = en["name"]
            if d.get("badge"):
                dict_map[d["badge"]] = en["short"]

    for zh, en in POLITY_EXTRA_EN.items():
        dict_map.setdefault(zh, en)

    dynasties = {d["key"]: ERAS_EN[d["key"]] for d in dyn if d["key"] in ERA_EN_KEYS}
    corridors = {k: list(v) for k, v in CORRIDORS_EN.items()}

    strings = {
        "title": "Anatolia Chronicle · Historical Atlas of Asia Minor",
        "brand_seal": "安纳托利亚",
        "brand_sub": "Anatolia · Hittites → Present",
        "toggle_terrain": "Terrain & Rivers",
    }

    block = [
        MARK_A,
        "(function () {",
        "  var L = window.EN_LOCALE;",
        "  if (!L) return;",
        "  L.strings = L.strings || {};",
        "  Object.assign(L.strings, " + json.dumps(strings, ensure_ascii=False) + ");",
        "  L.dynasties = " + json.dumps(dynasties, ensure_ascii=False) + ";",
        "  L.corridors = " + json.dumps(corridors, ensure_ascii=False) + ";",
        "  L.dict = Object.assign(L.dict || {}, " + json.dumps(dict_map, ensure_ascii=False) + ");",
        "  L.milestones = " + json.dumps(MILESTONES_EN, ensure_ascii=False) + ";",
        "})();",
        MARK_B,
    ]
    payload = "\n".join(block)

    p = os.path.join(ROOT, "js/i18n_dict.js")
    s = open(p, encoding="utf-8").read()
    s = re.sub(re.escape(MARK_A) + r".*?" + re.escape(MARK_B), "", s, flags=re.S).rstrip() + "\n\n" + payload + "\n"
    open(p, "w", encoding="utf-8").write(s)
    print(f"i18n 覆盖写入：dynasties {len(dynasties)}、corridors {len(corridors)}、dict {len(dict_map)} 条，milestones 清空上游中国条目")


if __name__ == "__main__":
    main()
